function void uvm_component::set_local(uvm_resource_base rsrc) ;

  bit success;

  //set the local properties
  if((rsrc != null) && (rsrc.get_name() == "recording_detail")) begin
    `uvm_resource_builtin_int_read(success,
    rsrc,
    recording_detail,
    this)
  end

  if (!success) begin

    super.set_local(rsrc);
  end


endfunction


