                                 uvm_sequencer_base sequencer = null);
     set_use_sequence_info(1);
     if (parent_seq != null) begin
       set_parent_sequence(parent_seq);
     end

     if (sequencer == null && m_parent_sequence != null) begin
       sequencer = m_parent_sequence.get_sequencer();
     end

